@RunWith(MockitoJUnitRunner.class)
public class CommandLineRunner_createOptions_TriageGen1Test {

  private CommandLineRunner runner;
  private CommandLineRunner.Flags flags;
  private PrintStream out = mock(PrintStream.class);
  private PrintStream err = mock(PrintStream.class);

  // Since CommandLineRunner is likely testing a class with internal Flags, 
  // we assume Flags is accessible or we use reflection/subclassing.
  // Given the prompt, we will simulate the state of the 'flags' field.

  private static class TestableCommandLineRunner extends CommandLineRunner {
    public TestableCommandLineRunner(String[] args, PrintStream out, PrintStream err) {
      super(args, out, err);
    }

    // Expose protected method for testing
    @Override
    public CompilerOptions createOptions() {
      return super.createOptions();
    }

    // Helper to inject flags if they are protected/package-private
    public void setFlags(Flags flags) {
      this.flags = flags;
    }
  }

  @Before
  public void setUp() {
    // We initialize with empty args to satisfy constructor
    runner = spy(new TestableCommandLineRunner(new String[]{}, out, err));
    flags = new CommandLineRunner.Flags();

    // Default setups to avoid NPEs in the method logic
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;
    flags.formatting = Collections.emptyList();
    flags.process_closure_primitives = false;

    runner.setFlags(flags);
  }

  @Test
  public void createOptions_basicFlow() {
    // Arrange
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;
    flags.process_closure_primitives = true;

    doNothing().when(runner).initOptionsFromFlags(any(CompilerOptions.class));

    // Act
    CompilerOptions options = runner.createOptions();

    // Assert
    assertThat(options).isNotNull();
    verify(flags.compilation_level).setOptionsForCompilationLevel(options);
    verify(flags.warning_level).setOptionsForWarningLevel(options);
    assertThat(options.closurePass).isTrue();
    verify(runner).initOptionsFromFlags(options);
  }

  @Test
  public void createOptions_withDebugTrue() {
    // Arrange
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = true;
    flags.formatting = Collections.emptyList();

    doNothing().when(runner).initOptionsFromFlags(any(CompilerOptions.class));

    // Act
    CompilerOptions options = runner.createOptions();

    // Assert
    verify(flags.compilation_level).setDebugOptionsForCompilationLevel(options);
  }

  @Test
  public void createOptions_withFormattingOptions() {
    // Arrange
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;

    FormattingOption mockFormatting = mock(FormattingOption.class);
    flags.formatting = Arrays.asList(mockFormatting);

    doNothing().when(runner).initOptionsFromFlags(any(CompilerOptions.class));

    // Act
    CompilerOptions options = runner.createOptions();

    // Assert
    verify(mockFormatting).applyToOptions(options);
  }

  @Test
  public void createOptions_withMultipleFormattingOptions() {
    // Arrange
    flags.compilation_level = mock(CompilationLevel.class);
    flags.warning_level = mock(WarningLevel.class);
    flags.debug = false;

    FormattingOption fmt1 = mock(FormattingOption.class);
    FormattingOption fmt2 = mock(FormattingOption.class);
    flags.formatting = Arrays.asList(fmt1, fmt2);

    doNothing().when(runner).initOptionsFromFlags(any(CompilerOptions.class));

    // Act
    CompilerOptions options = runner.createOptions();

    // Assert
    verify(fmt1).applyToOptions(options);
    verify(fmt2).applyToOptions(options);
  }
}
